from pathlib import Path

p = Path('scripts/build_v50.py')
s = p.read_text(encoding='utf-8')
orig = s

# Rear mounting backstop for each side module.
#
# Frozen riding-direction convention for v50 from this pass onward:
#   -X = bicycle front / saddle side
#   +X = bicycle rear / wheel end
# Therefore CLAMP_X max() is the rear clamp.
#
# The THRON² EQP diagonal stay starts behind the rear clamp and runs forward as
# it drops. The mounting aid must therefore exist only behind the rear clamp,
# not between both clamps. It remains an assembly/anti-flop aid, never a third
# structural rack clamp.
anchor = '''BASE = BASE.removeSplitter()\n\n# -----------------------------\n# Rack lower clamp\n# -----------------------------'''
if anchor not in s:
    raise SystemExit('Could not locate final BASE before rack lower clamp')

replacement = '''BASE = BASE.removeSplitter()\n\n# -----------------------------\n# Rear-only integrated mounting backstop\n# -----------------------------\nRIDE_FRONT_X_SIGN = -1\nRIDE_REAR_X_SIGN = 1\nFRONT_CLAMP_X = min(CLAMP_X)\nREAR_CLAMP_X = max(CLAMP_X)\n\n# The photo-derived useful stay-contact zone is roughly 60..100 mm behind the\n# rear clamp centre over the planned 50 mm hanging height. Use that as a broad\n# contact window rather than pretending the still-unmeasured diagonal stay has\n# an exact CAD axis. The 40 mm X-width therefore brackets the expected contact\n# while keeping a large service gap behind the rear clamp body.\nMOUNT_BACKSTOP_X_FROM_REAR_CLAMP = 60.0\nMOUNT_BACKSTOP_W_X = 40.0\nMOUNT_BACKSTOP_H = 50.0\nMOUNT_BACKSTOP_T_Y = 4.0\nMOUNT_BACKSTOP_X0 = REAR_CLAMP_X + MOUNT_BACKSTOP_X_FROM_REAR_CLAMP\nMOUNT_BACKSTOP_X1 = MOUNT_BACKSTOP_X0 + MOUNT_BACKSTOP_W_X\nMOUNT_BACKSTOP_Y0 = -16.0\nMOUNT_BACKSTOP_Z0 = -42.0\nMOUNT_BACKSTOP_Z1 = MOUNT_BACKSTOP_Z0 + MOUNT_BACKSTOP_H\n\n# Bicycle-bag-like flat stop face: one per BASE, behind the rear clamp only.\nMOUNT_BACKSTOP_PANEL = box(MOUNT_BACKSTOP_X0, MOUNT_BACKSTOP_Y0,\n                           MOUNT_BACKSTOP_Z0, MOUNT_BACKSTOP_W_X,\n                           MOUNT_BACKSTOP_T_Y, MOUNT_BACKSTOP_H)\n\n# Strong lower root. It overlaps the hanging panel vertically and extends deep\n# toward the BASE. Z starts at 7 mm, safely above the 12.42 mm rack tube crown\n# at Z=6.21, so strength is added without creating a hidden tube collision.\nMOUNT_BACKSTOP_ROOT_Y0 = -16.0\nMOUNT_BACKSTOP_ROOT_Y1 = 4.0\nMOUNT_BACKSTOP_ROOT_Z0 = 7.0\nMOUNT_BACKSTOP_ROOT_Z1 = 22.0\nMOUNT_BACKSTOP_ROOT = box(MOUNT_BACKSTOP_X0, MOUNT_BACKSTOP_ROOT_Y0,\n                          MOUNT_BACKSTOP_ROOT_Z0, MOUNT_BACKSTOP_W_X,\n                          MOUNT_BACKSTOP_ROOT_Y1-MOUNT_BACKSTOP_ROOT_Y0,\n                          MOUNT_BACKSTOP_ROOT_Z1-MOUNT_BACKSTOP_ROOT_Z0)\n\n# Upper gusset: broad material path from the rear stop into the rear I-beam /\n# clamp root. Near the rear clamp it stays high above the lower-clamp sweep; at\n# the stop it drops to the root block. The top remains 0.79 mm below the box\n# support datum so the box still bears on the intended arm flanges.\nMOUNT_BACKSTOP_GUSSET_Y0 = -16.0\nMOUNT_BACKSTOP_GUSSET_Y1 = 4.0\nMOUNT_BACKSTOP_GUSSET_TOP_Z = 38.75\nMOUNT_BACKSTOP_REAR_ROOT_X0 = REAR_CLAMP_X - ARM_W/2.0\n_mount_backstop_profile = [\n    App.Vector(MOUNT_BACKSTOP_X0, MOUNT_BACKSTOP_GUSSET_Y0, 7.0),\n    App.Vector(MOUNT_BACKSTOP_X1, MOUNT_BACKSTOP_GUSSET_Y0, 7.0),\n    App.Vector(MOUNT_BACKSTOP_X1, MOUNT_BACKSTOP_GUSSET_Y0, MOUNT_BACKSTOP_GUSSET_TOP_Z),\n    App.Vector(MOUNT_BACKSTOP_REAR_ROOT_X0, MOUNT_BACKSTOP_GUSSET_Y0, MOUNT_BACKSTOP_GUSSET_TOP_Z),\n    App.Vector(MOUNT_BACKSTOP_REAR_ROOT_X0, MOUNT_BACKSTOP_GUSSET_Y0, 24.0),\n    App.Vector(MOUNT_BACKSTOP_X0, MOUNT_BACKSTOP_GUSSET_Y0, 20.0),\n]\n_mount_backstop_wire = Part.makePolygon(_mount_backstop_profile + [_mount_backstop_profile[0]])\nMOUNT_BACKSTOP_GUSSET = Part.Face(_mount_backstop_wire).extrude(\n    App.Vector(0, MOUNT_BACKSTOP_GUSSET_Y1-MOUNT_BACKSTOP_GUSSET_Y0, 0))\n\n# Quantify the actual connection. The rear gusset must substantially overlap the\n# rear I-beam root, and must not reach the front I-beam root.\n_rear_root_ref = make_i_beam_y(REAR_CLAMP_X, -8.0, 36.0)\n_front_root_ref = make_i_beam_y(FRONT_CLAMP_X, -8.0, 36.0)\nMOUNT_BACKSTOP_REAR_ROOT_OVERLAP_MM3 = MOUNT_BACKSTOP_GUSSET.common(_rear_root_ref).Volume\nMOUNT_BACKSTOP_FRONT_ROOT_OVERLAP_MM3 = MOUNT_BACKSTOP_GUSSET.common(_front_root_ref).Volume\n\nMOUNT_BACKSTOP = fuse_all([\n    MOUNT_BACKSTOP_PANEL,\n    MOUNT_BACKSTOP_ROOT,\n    MOUNT_BACKSTOP_GUSSET,\n])\nBASE = BASE.fuse(MOUNT_BACKSTOP).removeSplitter()\n\n# Preserve both frozen rack-pin bores after every final BASE fusion.\nfor xc in CLAMP_X:\n    BASE = BASE.cut(cyl_x(PIN_HOLE_D/2.0, 40.0, xc-20.0, PIN_Y, PIN_Z))\nBASE = BASE.removeSplitter()\n\nif not BASE.isValid() or len(BASE.Solids) != 1:\n    raise RuntimeError('Rear-only mounting backstop did not fuse into one valid BASE solid')\n\n# -----------------------------\n# Rack lower clamp\n# -----------------------------'''
s = s.replace(anchor, replacement, 1)

validation_anchor = "for name, sh in PARTS.items():\n"
if validation_anchor not in s:
    raise SystemExit('Could not locate v50 export/validation gate')
validation = '''V['mounting_backstop'] = {\n    'purpose': 'rear_diagonal_stay_assembly_aid_only_non_load_bearing',\n    'riding_axis': 'X',\n    'front_direction': '-X',\n    'rear_direction': '+X',\n    'front_clamp_x_mm': FRONT_CLAMP_X,\n    'rear_clamp_x_mm': REAR_CLAMP_X,\n    'architecture': 'single_rear_40mm_panel_with_deep_root_and_rear_i_beam_gusset',\n    'panel_x_range_mm': [MOUNT_BACKSTOP_X0, MOUNT_BACKSTOP_X1],\n    'panel_x_width_mm': MOUNT_BACKSTOP_W_X,\n    'panel_height_mm': MOUNT_BACKSTOP_H,\n    'panel_thickness_y_mm': MOUNT_BACKSTOP_T_Y,\n    'panel_y_range_mm': [MOUNT_BACKSTOP_Y0, MOUNT_BACKSTOP_Y0+MOUNT_BACKSTOP_T_Y],\n    'panel_z_range_mm': [MOUNT_BACKSTOP_Z0, MOUNT_BACKSTOP_Z1],\n    'contact_window_behind_rear_clamp_center_mm': [\n        round(MOUNT_BACKSTOP_X0-REAR_CLAMP_X, 3),\n        round(MOUNT_BACKSTOP_X1-REAR_CLAMP_X, 3),\n    ],\n    'clearance_from_rear_clamp_body_mm': round(MOUNT_BACKSTOP_X0-(REAR_CLAMP_X+17.0), 3),\n    'root_block_y_depth_mm': MOUNT_BACKSTOP_ROOT_Y1-MOUNT_BACKSTOP_ROOT_Y0,\n    'root_block_z_height_mm': MOUNT_BACKSTOP_ROOT_Z1-MOUNT_BACKSTOP_ROOT_Z0,\n    'upper_gusset_top_z_mm': MOUNT_BACKSTOP_GUSSET_TOP_Z,\n    'gap_below_box_support_mm': round(BOX_SUPPORT_Z-MOUNT_BACKSTOP_GUSSET_TOP_Z, 3),\n    'rear_i_beam_root_overlap_mm3': round(MOUNT_BACKSTOP_REAR_ROOT_OVERLAP_MM3, 3),\n    'front_i_beam_root_overlap_mm3': round(MOUNT_BACKSTOP_FRONT_ROOT_OVERLAP_MM3, 6),\n    'rack_pin_bores_recut_after_fusion': True,\n    'primary_load_path': 'two_rack_clamps_only',\n}\nif V['mounting_backstop']['front_direction'] != '-X' or V['mounting_backstop']['rear_direction'] != '+X':\n    failures.append('Riding-direction convention for mounting backstop is not frozen as -X front / +X rear')\nif V['mounting_backstop']['rear_clamp_x_mm'] != max(CLAMP_X):\n    failures.append('Mounting backstop is not referenced to the rear clamp')\nif abs(V['mounting_backstop']['panel_height_mm']-50.0) > 0.01:\n    failures.append('Rear mounting backstop is not the requested 50 mm hanging height')\nif V['mounting_backstop']['panel_x_range_mm'][0] <= REAR_CLAMP_X + 17.0:\n    failures.append('Rear mounting backstop is not fully behind the rear clamp body')\nif V['mounting_backstop']['clearance_from_rear_clamp_body_mm'] < 35.0:\n    failures.append('Rear mounting backstop leaves too little service space behind the rear clamp')\nif V['mounting_backstop']['contact_window_behind_rear_clamp_center_mm'][0] < 55.0:\n    failures.append('Rear mounting backstop starts too close to the rear clamp for the falling diagonal stay')\nif V['mounting_backstop']['contact_window_behind_rear_clamp_center_mm'][1] > 105.0:\n    failures.append('Rear mounting backstop extends beyond the intended photo-derived stay contact window')\nif V['mounting_backstop']['root_block_y_depth_mm'] < 18.0:\n    failures.append('Rear mounting backstop root block is too shallow for a robust BASE connection')\nif not (0.5 <= V['mounting_backstop']['gap_below_box_support_mm'] <= 1.5):\n    failures.append('Rear mounting backstop gusset top must stay 0.5..1.5 mm below box support')\nif V['mounting_backstop']['rear_i_beam_root_overlap_mm3'] < 1000.0:\n    failures.append('Rear mounting backstop does not substantially overlap the rear I-beam root')\nif V['mounting_backstop']['front_i_beam_root_overlap_mm3'] > 1e-4:\n    failures.append('Rear mounting backstop incorrectly reaches the front I-beam root')\nif not V['mounting_backstop']['rack_pin_bores_recut_after_fusion']:\n    failures.append('Rear mounting backstop does not preserve rack-pin service bores')\n\n'''
s = s.replace(validation_anchor, validation + validation_anchor, 1)

# Keep generated notes aligned with the delivered geometry. Accept prior note
# variants because this pass runs after several historical architecture passes.
for old_note in [
    "f.write('No diagonal-stay V saddle. Anti-rotation is integrated into both rack-clamp roots.\\n')",
    "f.write('No diagonal-stay clamp: each BASE has a 50 mm integral flat mounting backstop between its two rack clamps; primary load remains on the rack clamps.\\n')",
    "f.write('Each BASE has a non-clamping 100 mm diagonal-stay mounting backstop, tapered upward into both I-beam roots; primary load remains on the two rack clamps.\\n')",
]:
    s = s.replace(
        old_note,
        "f.write('Each BASE has one rear-only 50 mm diagonal-stay mounting backstop behind the rear rack clamp, strongly gusseted into that rear I-beam root; primary load remains on the two rack clamps.\\n')",
    )

if s == orig:
    raise SystemExit('Rear mounting-backstop fixup made no changes')

p.write_text(s, encoding='utf-8')
print('Applied v50 rear mounting backstop: +X rear, 60..100 mm behind rear clamp, deep root + rear I-beam gusset')
